package main

import "fmt"

type User struct {
	Name   string
	Active bool
}

func activateValue(users map[int]User, id int) bool {
	user, ok := users[id]
	if !ok {
		return false
	}
	user.Active = true
	users[id] = user
	return true
}

func activatePointer(users map[int]*User, id int) bool {
	user, ok := users[id]
	if !ok || user == nil {
		return false
	}
	user.Active = true
	return true
}

func main() {
	values := map[int]User{7: {Name: "Mina"}}
	pointers := map[int]*User{8: {Name: "Noah"}}

	activateValue(values, 7)
	activatePointer(pointers, 8)
	fmt.Println(values[7], *pointers[8])
}
